<script>
const $=id=>document.getElementById(id);let me=null,dash=null,rows=[];const n=v=>Number(v||0),fmt=v=>new Intl.NumberFormat('id-ID').format(n(v)),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(url,opt={}){const r=await fetch(url,{credentials:'same-origin',cache:'no-store',...opt});const d=await r.json().catch(()=>({ok:false,message:'Response tidak valid'}));if(r.status===401)throw Error('Sesi login habis');if(!r.ok||d.ok===false)throw Error(d.message||d.error||('HTTP '+r.status));return d}
const statusOf=o=>String(o.status||o.result||'').toUpperCase();function classify(o){const s=statusOf(o);if(/MENOLAK|REJECT|REFUSE/.test(s))return'reject';if(/CLOSE|CLOSED|DONE|SELESAI|COMPLET/.test(s))return'close';if(/UPDATE|PROGRESS|PENDING/.test(s))return'update';return'open'}
function clock(){const d=new Date();$('clock').textContent=d.toLocaleTimeString('id-ID',{hour12:false})+' WIB';$('sideClock').textContent=d.toLocaleTimeString('id-ID',{hour12:false})+' WIB';$('dateLabel').textContent=new Intl.DateTimeFormat('id-ID',{weekday:'long',day:'numeric',month:'long',year:'numeric'}).format(d)}setInterval(clock,1000);clock();
function flat(p){if(Array.isArray(p))return p;if(Array.isArray(p.orders))return p.orders;if(Array.isArray(p.data))return p.data;if(Array.isArray(p.items))return p.items;let a=[];(p.areas||[]).forEach(x=>(x.orders||[]).forEach(o=>a.push({...o,area:o.area||x.area})));return a}
function summary(a){const c={open:0,close:0,update:0,reject:0};a.forEach(o=>c[classify(o)]++);return c}
function kpis(c){const t=c.open+c.close+c.update+c.reject;$('total').textContent=fmt(t);$('open').textContent=fmt(c.open);$('close').textContent=fmt(c.close);$('update').textContent=fmt(c.update);$('reject').textContent=fmt(c.reject);$('openPct').textContent=(t?Math.round(c.open/t*1000)/10:0)+'%';$('closePct').textContent=(t?Math.round(c.close/t*1000)/10:0)+'%';$('updatePct').textContent=(t?Math.round(c.update/t*1000)/10:0)+'%';$('rejectPct').textContent=(t?Math.round(c.reject/t*1000)/10:0)+'%';$('donutTotal').textContent=fmt(t);$('sOpen').textContent=fmt(c.open)+' ('+(t?Math.round(c.open/t*1000)/10:0)+'%)';$('sClose').textContent=fmt(c.close)+' ('+(t?Math.round(c.close/t*1000)/10:0)+'%)';$('sUpdate').textContent=fmt(c.update)+' ('+(t?Math.round(c.update/t*1000)/10:0)+'%)';$('sReject').textContent=fmt(c.reject)+' ('+(t?Math.round(c.reject/t*1000)/10:0)+'%)';const a=c.open/t*360||0,b=c.close/t*360||0,d=c.update/t*360||0;$('donut').style.background=`conic-gradient(var(--green) 0 ${a}deg,var(--purple) ${a}deg ${a+b}deg,var(--yellow) ${a+b}deg ${a+b+d}deg,var(--red) ${a+b+d}deg 360deg)`}
function drawLines(data){const c=$('trend'),ctx=c.getContext('2d'),w=c.clientWidth||600,h=c.clientHeight||235,d=devicePixelRatio||1;c.width=w*d;c.height=h*d;ctx.scale(d,d);ctx.clearRect(0,0,w,h);ctx.strokeStyle='#6282a125';for(let i=1;i<6;i++){let y=20+i*(h-48)/6;ctx.beginPath();ctx.moveTo(12,y);ctx.lineTo(w-8,y);ctx.stroke()}const a=(data&&data.length)?data:Array.from({length:9},(_,i)=>({label:['Jan','Feb','Mar','Apr','Mei','Jun','Jul','Agu','Sep'][i],open:0,close:0,update:0}));const max=Math.max(1,...a.map(x=>Math.max(n(x.open||x.total_open),n(x.close||x.total_close),n(x.update||x.total_update))));[['open','#19c9ff'],['close','#a64cff'],['update','#ffc531']].forEach(([key,col])=>{ctx.beginPath();a.forEach((x,i)=>{const v=n(x[key]||x['total_'+key]),px=18+i*(w-36)/Math.max(1,a.length-1),py=h-28-v/max*(h-58);i?ctx.lineTo(px,py):ctx.moveTo(px,py)});ctx.strokeStyle=col;ctx.lineWidth=2;ctx.shadowColor=col;ctx.shadowBlur=7;ctx.stroke();ctx.shadowBlur=0});ctx.fillStyle='#71869d';ctx.font='8px sans-serif';a.forEach((x,i)=>{const px=18+i*(w-36)/Math.max(1,a.length-1);ctx.fillText(String(x.label||''),px-8,h-10)})}
function drawTraffic(){const c=$('trafficCanvas'),ctx=c.getContext('2d'),w=c.clientWidth||500,h=c.clientHeight||210,d=devicePixelRatio||1;c.width=w*d;c.height=h*d;ctx.scale(d,d);ctx.clearRect(0,0,w,h);ctx.strokeStyle='#6282a122';for(let y=25;y<h-20;y+=34){ctx.beginPath();ctx.moveTo(6,y);ctx.lineTo(w-6,y);ctx.stroke()}[['#19c9ff',.1],['#a64cff',.3],['#ffc531',.55]].forEach(([col,p])=>{ctx.beginPath();for(let x=0;x<=w;x+=5){const y=h/2+Math.sin(x/35+p*8)*h*.11+Math.sin(x/91+p*4)*h*.08;x?ctx.lineTo(x,y):ctx.moveTo(x,y)}ctx.strokeStyle=col;ctx.lineWidth=2;ctx.shadowColor=col;ctx.shadowBlur=6;ctx.stroke();ctx.shadowBlur=0})}
function leaders(a){const m={};a.forEach(o=>{const name=o.assigned_technician||o.technician_name||'Unassigned',key=name;if(!m[key])m[key]={name,total:0,close:0,nik:o.technician_nik||''};m[key].total++;if(classify(o)==='close')m[key].close++});let list=Object.values(m).sort((x,y)=>y.close-x.close||y.total-x.total);if(dash&&Array.isArray(dash.leaderboard)&&dash.leaderboard.length)list=dash.leaderboard.map(x=>({name:x.name||x.technician_name||'-',nik:x.nik||'',total:n(x.total||x.close),close:n(x.close||x.total)}));list=list.slice(0,5);const max=Math.max(1,...list.map(x=>x.close));$('leaders').innerHTML=list.map((x,i)=>`<div class="leader"><div class="num">${i+1}</div><div class="linfo"><b>${esc(x.name)}</b><small>${esc(x.nik)}</small></div><div class="meter"><span style="width:${Math.max(5,x.close/max*100)}%"></span></div><div class="lval">${fmt(x.close)}</div></div>`).join('')||'<div class="muted">Belum ada data teknisi.</div>'}
function areas(a){const m={};a.forEach(o=>{const k=o.area||o.sto||'LAINNYA';m[k]=(m[k]||0)+1});const list=Object.entries(m).sort((x,y)=>y[1]-x[1]).slice(0,7),max=Math.max(1,...list.map(x=>x[1]));$('areaBars').innerHTML=list.map(([k,v])=>`<div class="bar-item"><div class="bar-outer"><div class="bar" style="height:${Math.max(5,v/max*100)}%"></div></div><b>${fmt(v)}</b><small>${esc(k)}</small></div>`).join('')||'<div class="muted">Belum ada area.</div>'}
function recent(a){$('recent').innerHTML=a.slice(0,5).map((o,i)=>`<div class="recent-row"><time>${['14:05','13:42','12:30','11:15','10:48'][i]}</time><span class="act">${classify(o)==='close'?'✓':classify(o)==='update'?'↻':'+'}</span><b>Order ${esc(o.service_number||o.inet||'-')} update status ${esc(statusOf(o)||'OPEN')}</b><small>${esc(o.assigned_technician||o.technician_name||'System')}</small></div>`).join('')||'<div class="muted">Belum ada aktivitas.</div>'}
function orders(a){const q=($('orderSearch').value||$('globalSearch').value||'').toLowerCase();const b=a.filter(o=>!q||JSON.stringify(o).toLowerCase().includes(q)).slice(0,80);$('orderMeta').textContent=fmt(a.length)+' DATA';$('orders').innerHTML=b.map(o=>`<div class="order"><b>${esc(o.service_number||o.inet||'-')}</b><div><b>${esc(o.customer_name||'-')}</b><small>${esc(o.address||'-')}<br>RCA: ${esc(o.rca||'-')} • ONU RX: ${esc(o.onu_rx||'-')}</small></div><small>${esc(o.assigned_technician||'-')} • ${esc(statusOf(o)||'OPEN')}</small></div>`).join('')||'<div class="muted">Tidak ada order.</div>'}
function rca(a,d){let list=Array.isArray(d?.items)?d.items:[];if(!list.length){const m={};a.forEach(o=>{const k=o.rca||'-';m[k]=(m[k]||0)+1});list=Object.entries(m).sort((x,y)=>y[1]-x[1]).map(x=>({label:x[0],count:x[1]}))}$('rca').innerHTML=list.slice(0,10).map(x=>`<div class="recent-row" style="grid-template-columns:1fr 45px"><span>${esc(x.label||x.rca||'-')}</span><b style="text-align:right">${fmt(x.count||x.total)}</b></div>`).join('')||'<div class="muted">Belum ada RCA.</div>'}
async function load(){try{$('lastSync').textContent=new Date().toLocaleTimeString('id-ID',{hour12:false})+' WIB';const p=await api('/api/web-orders?force=1');rows=flat(p);let c=summary(rows);try{dash=await api('/api/web-dashboard?period='+encodeURIComponent($('period').value));const s=dash.summary||{};if(n(s.total_open))c.open=n(s.total_open);if(n(s.total_close))c.close=n(s.total_close);if(n(s.total_update))c.update=n(s.total_update);if(n(s.total_reject))c.reject=n(s.total_reject)}catch(e){}let r={};try{r=await api('/api/web-rca')}catch(e){}kpis(c);drawLines(dash?.trend||[]);drawTraffic();leaders(rows);areas(rows);recent(rows);orders(rows);rca(rows,r)}catch(e){if(/sesi|login/i.test(e.message))showLogin(e.message);else console.error(e)}}
function showLogin(msg=''){$('loginView').classList.remove('hidden');$('app').classList.add('hidden');$('loginError').textContent=msg}function showApp(){$('loginView').classList.add('hidden');$('app').classList.remove('hidden');$('userName').textContent=me?.name||'Technician';$('userMeta').textContent=(me?.role||'HSA')+' • STO '+(me?.sto||'-');$('avatar').textContent=(me?.name||'M').slice(0,1).toUpperCase();load();}
$('loginForm').addEventListener('submit',async e=>{e.preventDefault();try{const d=await api('/api/web-login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({nik:$('nik').value.trim(),password:$('password').value})});me=d.user;showApp()}catch(err){$('loginError').textContent=err.message}});$('period').addEventListener('change',load);$('refresh').addEventListener('click',load);$('orderSearch').addEventListener('input',()=>orders(rows));$('globalSearch').addEventListener('input',()=>orders(rows));$('logout').addEventListener('click',async()=>{await fetch('/api/web-logout',{method:'POST',credentials:'same-origin'});showLogin()});$('menu').addEventListener('click',()=>document.body.classList.toggle('menu-open'));document.querySelectorAll('[data-target]').forEach(b=>b.addEventListener('click',()=>{const t=$(b.dataset.target);if(t)t.scrollIntoView({behavior:'smooth'});document.querySelectorAll('.nav button').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.body.classList.remove('menu-open')}));window.addEventListener('resize',()=>{drawTraffic();drawLines(dash?.trend||[])});(async()=>{try{const d=await api('/api/web-session');me=d.user;showApp()}catch{showLogin()}})();
</script>
